package org.apache.commons.compress.archivers.tar;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

import java.io.ByteArrayOutputStream;
import java.io.File;
import java.io.IOException;

import org.apache.commons.compress.archivers.ArchiveEntry;
import org.junit.Test;

public class TarArchiveOutputStreamTest {

    @Test
    public void testDefaultConstructorAndFinish() throws IOException {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        TarArchiveOutputStream out = new TarArchiveOutputStream(baos);
        out.finish();
        out.close();
        assertTrue(baos.size() > 0);
    }

    @Test
    public void testBlockAndRecordSizeConstructors() throws IOException {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        TarArchiveOutputStream out = new TarArchiveOutputStream(baos, 1024, 512);
        assertEquals(512, out.getRecordSize());
        out.finish();
        out.close();
    }

    @Test
    public void testLongFileModeSetting() throws IOException {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        TarArchiveOutputStream out = new TarArchiveOutputStream(baos);
        out.setLongFileMode(TarArchiveOutputStream.LONGFILE_GNU);
        out.finish();
        out.close();
    }

    @Test
    public void testPutAndCloseEntry() throws IOException {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        TarArchiveOutputStream out = new TarArchiveOutputStream(baos);
        TarArchiveEntry entry = new TarArchiveEntry("test.txt");
        entry.setSize(4);
        out.putArchiveEntry(entry);
        out.write("test".getBytes());
        out.closeArchiveEntry();
        out.finish();
        out.close();
        assertTrue(baos.size() > 0);
    }

    @Test
    public void testCreateArchiveEntry() throws IOException {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        TarArchiveOutputStream out = new TarArchiveOutputStream(baos);
        File tempFile = File.createTempFile("compress", "tmp");
        tempFile.deleteOnExit();
        ArchiveEntry entry = out.createArchiveEntry(tempFile, "relative/path");
        assertNotNull(entry);
        out.close();
    }

    @Test(expected = IOException.class)
    public void testUnclosedEntryThrowsOnFinish() throws IOException {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        TarArchiveOutputStream out = new TarArchiveOutputStream(baos);
        TarArchiveEntry entry = new TarArchiveEntry("test.txt");
        entry.setSize(4);
        out.putArchiveEntry(entry);
        out.finish();
    }
}
